                    AND (SELECT `date_created` FROM `caches` WHERE `cache_id`=NEW.`object_id`) < LEFT(NOW(),10)
                    AND (SELECT `status` FROM `caches` WHERE `caches`.`cache_id`=NEW.`object_id`) != 5
